+
+    fn begin_visual_selection(
+        &mut self,
+        kind: UiVisualMode,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        let cursor = self.focus_cursor_position(right_content, right_cursor_column);
+        self.mode = UiMode::Visual(kind);
+        self.visual_selection = Some(VisualSelection {
+            focus: self.focus,
+            anchor: cursor,
+            cursor,
+        });
+    }
+
+    fn handle_visual_key(
+        &mut self,
+        key: UiKey,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.mode = UiMode::Command;
+                self.clear_visual_selection();
+                Vec::new()
+            }
+            UiKey::Char('v') => {
+                self.set_visual_mode(UiVisualMode::Character, right_content, right_cursor_column);
+                Vec::new()
+            }
+            UiKey::Char('V') => {
+                self.set_visual_mode(UiVisualMode::Line, right_content, right_cursor_column);
+                Vec::new()
+            }
+            UiKey::CtrlV => {
+                self.set_visual_mode(UiVisualMode::Block, right_content, right_cursor_column);
+                Vec::new()
+            }
+            UiKey::Char('y') => self.copy_visual_selection(right_content, None),
+            UiKey::Char('Y') => self.copy_visual_selection(right_content, Some(UiVisualMode::Line)),
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_cursor(0, -1, right_content);
+                Vec::new()
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_cursor(1, 0, right_content);
+                Vec::new()
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_cursor(-1, 0, right_content);
+                Vec::new()
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_cursor(0, 1, right_content);
+                Vec::new()
+            }
+            _ => Vec::new(),
+        }
+    }
+
+    fn set_visual_mode(
+        &mut self,
+        kind: UiVisualMode,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        if self.visual_selection.is_none() {
+            self.begin_visual_selection(kind, right_content, right_cursor_column);
+        } else {
+            self.mode = UiMode::Visual(kind);
+        }
+    }
+
+    fn move_visual_cursor(&mut self, line_delta: isize, column_delta: isize, right_content: &str) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.visual_lines(selection.focus, right_content);
+        let next = TextPosition {
+            line: selection.line_with_delta(line_delta),
+            column: selection.column_with_delta(column_delta),
+        };
+        let next = clamp_text_position(next, &lines);
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.cursor = next;
+        }
+    }
+
+    fn copy_visual_selection(
+        &mut self,
+        right_content: &str,
+        override_mode: Option<UiVisualMode>,
+    ) -> Vec<UiAction> {
+        let Some(selection) = self.visual_selection else {
+            return Vec::new();
+        };
+        let kind = override_mode.unwrap_or_else(|| match self.mode {
+            UiMode::Visual(kind) => kind,
+            UiMode::Command | UiMode::Insert | UiMode::Prompt => UiVisualMode::Character,
+        });
+        let lines = self.visual_lines(selection.focus, right_content);
+        let text = selected_text(&lines, selection, kind);
+        self.clipboard_text = Some(text.clone());
+        self.pending_clipboard_text.replace(Some(text.clone()));
+        self.mode = UiMode::Command;
+        self.clear_visual_selection();
+        vec![UiAction::CopySelection(text)]
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn focus_cursor_position(
+        &self,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> TextPosition {
+        let lines = self.visual_lines(self.focus, right_content);
+        let position = match self.focus {
+            PaneFocus::Left => TextPosition {
+                line: self.control_selected,
+                column: 0,
+            },
+            PaneFocus::Right => TextPosition {
+                line: lines.len().saturating_sub(1),
+                column: right_cursor_column.unwrap_or(1).saturating_sub(1),
+            },
+        };
+        clamp_text_position(position, &lines)
+    }
+
+    fn visual_lines(&self, focus: PaneFocus, right_content: &str) -> Vec<String> {
+        match focus {
+            PaneFocus::Left => self
+                .left_widget_rows()
+                .into_iter()
+                .map(|row| row.text)
+                .collect(),
+            PaneFocus::Right => content_lines(right_content),
+        }
+    }
+
+    fn left_widget_rows(&self) -> Vec<LeftWidgetRow> {
+        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+        let mut rows = vec![LeftWidgetRow {
+            text: if self.control_selected == 0 {
+                "> work-leaf  command".to_string()
+            } else {
+                "  work-leaf  command".to_string()
+            },
+            ready: false,
+        }];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            let selected = self.control_selected == visible_position + 1;
+            rows.push(LeftWidgetRow {
+                text: compact_agent_row(agent, selected, inner_width),
+                ready: agent.ready,
+            });
+            if !agent.modified_files.is_empty() {
+                rows.push(LeftWidgetRow {
+                    text: format!(
+                        "    files: {}",
+                        agent
+                            .modified_files
+                            .iter()
+                            .map(|path| path.display().to_string())
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ),
+                    ready: false,
+                });
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    rows.push(LeftWidgetRow {
+                        text: format!(
+                            "    {label}: {}",
+                            agents
+                                .iter()
+                                .map(AgentId::as_str)
+                                .collect::<Vec<_>>()
+                                .join(", ")
+                        ),
+                        ready: false,
+                    });
+                }
+            }
+        }
+        rows
+    }
+
+    fn styled_line_for_selection(
+        &self,
+        focus: PaneFocus,
+        line_index: usize,
+        text: &str,
+    ) -> Spans<'static> {
+        let Some(kind) = (match self.mode {
+            UiMode::Visual(kind) => Some(kind),
+            UiMode::Command | UiMode::Insert | UiMode::Prompt => None,
+        }) else {
+            return Spans::from(vec![Span::raw(text.to_string())]);
+        };
+        let Some(selection) = self.visual_selection else {
+            return Spans::from(vec![Span::raw(text.to_string())]);
+        };
+        if selection.focus != focus {
+            return Spans::from(vec![Span::raw(text.to_string())]);
+        }
+        let Some((start, end)) =
+            selection_line_range(selection, kind, line_index, text.chars().count())
+        else {
+            return Spans::from(vec![Span::raw(text.to_string())]);
+        };
+        Spans::from(styled_spans(text, start, end))
+    }
 }

 impl UiMode {
     fn as_str(&self) -> &'static str {
         match self {
             Self::Command => "command",
             Self::Insert => "insert",
             Self::Prompt => "prompt",
+            Self::Visual(UiVisualMode::Character) => "visual",
+            Self::Visual(UiVisualMode::Line) => "visual-line",
+            Self::Visual(UiVisualMode::Block) => "visual-block",
         }
     }
 }
+
+impl VisualSelection {
+    fn line_with_delta(&self, delta: isize) -> usize {
+        self.cursor.line.saturating_add_signed(delta)
+    }
+
+    fn column_with_delta(&self, delta: isize) -> usize {
+        self.cursor.column.saturating_add_signed(delta)
+    }
+}
@@
 fn truncate_to_width(text: &str, width: usize) -> String {
     text.chars().take(width).collect()
 }
+
+fn content_lines(content: &str) -> Vec<String> {
+    if content.is_empty() {
+        vec![String::new()]
+    } else {
+        content.lines().map(ToString::to_string).collect()
+    }
+}
+
+fn clamp_text_position(position: TextPosition, lines: &[String]) -> TextPosition {
+    let line = position.line.min(lines.len().saturating_sub(1));
+    let line_len = lines
+        .get(line)
+        .map(|line| line.chars().count())
+        .unwrap_or_default();
+    let max_column = line_len.saturating_sub(1);
+    TextPosition {
+        line,
+        column: position.column.min(max_column),
+    }
+}
+
+fn selected_text(lines: &[String], selection: VisualSelection, kind: UiVisualMode) -> String {
+    lines
+        .iter()
+        .enumerate()
+        .filter_map(|(line_index, line)| {
+            selection_line_range(selection, kind, line_index, line.chars().count())
+                .map(|(start, end)| char_slice(line, start, end))
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selection_line_range(
+    selection: VisualSelection,
+    kind: UiVisualMode,
+    line_index: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    let (start, end) = ordered_positions(selection.anchor, selection.cursor);
+    if line_index < start.line || line_index > end.line {
+        return None;
+    }
+    match kind {
+        UiVisualMode::Line => Some((0, line_len)),
+        UiVisualMode::Character if start.line == end.line => {
+            Some((start.column.min(line_len), end.column.saturating_add(1).min(line_len)))
+        }
+        UiVisualMode::Character if line_index == start.line => {
+            Some((start.column.min(line_len), line_len))
+        }
+        UiVisualMode::Character if line_index == end.line => {
+            Some((0, end.column.saturating_add(1).min(line_len)))
+        }
+        UiVisualMode::Character => Some((0, line_len)),
+        UiVisualMode::Block => {
+            let start_column = selection.anchor.column.min(selection.cursor.column);
+            let end_column = selection.anchor.column.max(selection.cursor.column);
+            Some((
+                start_column.min(line_len),
+                end_column.saturating_add(1).min(line_len),
+            ))
+        }
+    }
+}
+
+fn ordered_positions(left: TextPosition, right: TextPosition) -> (TextPosition, TextPosition) {
+    if (left.line, left.column) <= (right.line, right.column) {
+        (left, right)
+    } else {
+        (right, left)
+    }
+}
+
+fn styled_spans(text: &str, start: usize, end: usize) -> Vec<Span<'static>> {
+    let char_count = text.chars().count();
+    let start = start.min(char_count);
+    let end = end.min(char_count);
+    if start >= end {
+        return vec![Span::raw(text.to_string())];
+    }
+    let before = char_slice(text, 0, start);
+    let selected = char_slice(text, start, end);
+    let after = char_slice(text, end, char_count);
+    let mut spans = Vec::new();
+    if !before.is_empty() {
+        spans.push(Span::raw(before));
+    }
+    spans.push(Span::styled(
+        selected,
+        Style::default().add_modifier(Modifier::REVERSED),
+    ));
+    if !after.is_empty() {
+        spans.push(Span::raw(after));
+    }
+    spans
+}
+
+fn char_slice(text: &str, start: usize, end: usize) -> String {
+    text.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn osc52_copy_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::new();
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = *chunk.get(1).unwrap_or(&0);
+        let third = *chunk.get(2).unwrap_or(&0);
