+fn clamp_text_position(position: TextPosition, lines: &[String]) -> TextPosition {
+    let line = position.line.min(lines.len().saturating_sub(1));
+    let line_len = lines
+        .get(line)
+        .map(|line| line.chars().count())
+        .unwrap_or_default();
+    let max_column = line_len.saturating_sub(1);
+    TextPosition {
+        line,
+        column: position.column.min(max_column),
+    }
+}
+
+fn selected_text(lines: &[String], selection: VisualSelection, kind: UiVisualMode) -> String {
+    lines
+        .iter()
+        .enumerate()
+        .filter_map(|(line_index, line)| {
+            selection_line_range(selection, kind, line_index, line.chars().count())
+                .map(|(start, end)| char_slice(line, start, end))
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selection_line_range(
+    selection: VisualSelection,
+    kind: UiVisualMode,
+    line_index: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    let (start, end) = ordered_positions(selection.anchor, selection.cursor);
+    if line_index < start.line || line_index > end.line {
+        return None;
+    }
+    match kind {
+        UiVisualMode::Line => Some((0, line_len)),
+        UiVisualMode::Character if start.line == end.line => {
+            Some((start.column.min(line_len), end.column.saturating_add(1).min(line_len)))
+        }
+        UiVisualMode::Character if line_index == start.line => {
+            Some((start.column.min(line_len), line_len))
+        }
+        UiVisualMode::Character if line_index == end.line => {
+            Some((0, end.column.saturating_add(1).min(line_len)))
+        }
+        UiVisualMode::Character => Some((0, line_len)),
+        UiVisualMode::Block => {
+            let start_column = selection.anchor.column.min(selection.cursor.column);
+            let end_column = selection.anchor.column.max(selection.cursor.column);
+            Some((
+                start_column.min(line_len),
+                end_column.saturating_add(1).min(line_len),
+            ))
+        }
+    }
+}
+
+fn ordered_positions(left: TextPosition, right: TextPosition) -> (TextPosition, TextPosition) {
+    if (left.line, left.column) <= (right.line, right.column) {
+        (left, right)
+    } else {
+        (right, left)
+    }
+}
+
+fn styled_spans(text: &str, start: usize, end: usize) -> Vec<Span<'static>> {
+    let char_count = text.chars().count();
+    let start = start.min(char_count);
+    let end = end.min(char_count);
+    if start >= end {
+        return vec![Span::raw(text.to_string())];
+    }
+    let before = char_slice(text, 0, start);
+    let selected = char_slice(text, start, end);
+    let after = char_slice(text, end, char_count);
+    let mut spans = Vec::new();
+    if !before.is_empty() {
+        spans.push(Span::raw(before));
+    }
+    spans.push(Span::styled(
+        selected,
+        Style::default().add_modifier(Modifier::REVERSED),
+    ));
+    if !after.is_empty() {
+        spans.push(Span::raw(after));
+    }
+    spans
+}
+
+fn char_slice(text: &str, start: usize, end: usize) -> String {
+    text.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn osc52_copy_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::new();
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = *chunk.get(1).unwrap_or(&0);
+        let third = *chunk.get(2).unwrap_or(&0);
+        let triple = ((first as u32) << 16) | ((second as u32) << 8) | third as u32;
+        encoded.push(TABLE[((triple >> 18) & 0x3f) as usize] as char);
+        encoded.push(TABLE[((triple >> 12) & 0x3f) as usize] as char);
+        if chunk.len() > 1 {
+            encoded.push(TABLE[((triple >> 6) & 0x3f) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+        if chunk.len() > 2 {
+            encoded.push(TABLE[(triple & 0x3f) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+    }
+    encoded
+}
